        'y2026' => '2026 Çıkmış Sorular',
        'y2025' => '2025 Çıkmış Sorular',
        'y2024' => '2024 Çıkmış Sorular',
        'y2023' => '2023 Çıkmış Sorular',
        'y2022' => '2022 Çıkmış Sorular',
        'y2021' => '2021 Çıkmış Sorular',
        'y2020' => '2020 Çıkmış Sorular',
        'animasyon' => 'Animasyonlu (diğer)',
        'ingilizce' => 'English',
        'diger' => 'Diğer',
    ];
}

function metro_video_ders_etiket(string $ders): string
{
    $g = metro_video_gruplar();
    if (isset($g[$ders])) {
        return $g[$ders];
    }
    $eski = [
        'trafik' => 'Trafik ve Çevre',
        'ilkyardim' => 'İlk Yardım',
        'arac' => 'Araç Tekniği',
        'adab' => 'Trafik Adabı',
        'direksiyon' => 'Direksiyon',
    ];
    return $eski[$ders] ?? $ders;
}

